"""자료를 한 페이지씩 렌더링하는 브라우저 내 뷰어."""
def page_viewer(value, pages, key):
    import streamlit.components.v2 as components
    return components.component('insight_pt_pages_v1',
        html='<section id="pt-pages" tabindex="0" aria-label="PT 페이지 뷰어"></section>',
        css='''#pt-pages{font:16px/1.65 system-ui,sans-serif;color:#29352c;--line:#d6dfcd;--green:#526e33;outline:none}
        *{box-sizing:border-box}button,select{font:inherit}button{cursor:pointer;border:1px solid var(--line);background:#f6f8ee;border-radius:10px;padding:9px 15px;color:inherit;min-height:44px}button:disabled{opacity:.4;cursor:default}button:focus-visible,select:focus-visible{outline:3px solid #8aab53;outline-offset:2px}.nav{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:8px 0 12px}.count{font-weight:750;color:var(--green);white-space:nowrap}.jump{min-width:0;flex:1;padding:10px;border:1px solid var(--line);border-radius:10px;background:white;color:inherit;max-width:100%}.paper{border:1px solid var(--line);border-top:4px solid #8ba667;border-radius:15px;background:#fffffa;padding:24px 30px;min-height:480px;max-height:76vh;overflow:auto;scrollbar-gutter:stable}.meta{font-size:.85rem;color:#60714b;margin:0 0 7px}.paper h2{font-size:1.4rem;line-height:1.45;margin:0 0 15px}.paper h3{font-size:1.03rem;margin:16px 0 7px}.prose{white-space:pre-wrap;overflow-wrap:anywhere;margin:0 0 12px;line-height:1.8}.block{padding:12px 16px;background:#f0f5e6;border-radius:10px;margin-top:13px}.block h3{margin:0 0 6px}.source{border-top:1px solid var(--line);padding-top:10px;margin-top:14px;font-size:.8rem;color:#65705c;overflow-wrap:anywhere}.foot{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px}.dots{display:flex;gap:5px;flex-wrap:wrap;margin-top:10px}.dots button{padding:5px 10px;min-height:36px;font-size:.87rem}.dots .active{background:var(--green);color:white;border-color:var(--green)}.chart-title{font-weight:750;margin:10px 0 2px}.chart-meta,.note{font-size:.82rem;line-height:1.6;color:#627058;white-space:pre-wrap}.chart{width:100%;display:block;max-height:330px}.table-wrap{overflow:auto;max-width:100%;margin-top:10px}.numbers{width:100%;border-collapse:collapse;font-size:.92rem;font-variant-numeric:tabular-nums}.numbers th{background:#eaf1dd}.numbers th,.numbers td{border:1px solid var(--line);padding:9px 12px;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere}.numbers td.n{text-align:right;font-size:1.05rem;font-weight:750}.bar-group{margin:12px 0}.category{font-weight:700;margin-bottom:4px}.bar-line{display:grid;grid-template-columns:minmax(80px,130px) minmax(90px,1fr) 90px;gap:9px;align-items:center;margin:5px 0}.bar-name{font-size:.86rem}.track{height:20px;position:relative;background:#eef2e7;border-radius:3px}.bar{position:absolute;height:100%;border-radius:3px}.zero{position:absolute;height:100%;border-left:1px solid #6c785d}.bar-value{text-align:right;font-size:1.06rem;font-weight:750;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:.85rem}.swatch{display:inline-block;width:12px;height:12px;margin-right:5px;border-radius:2px}.tip{font-size:.78rem;color:#718066;margin:8px 0 0}
        @media(max-width:620px){.paper{padding:17px 14px;min-height:420px;max-height:72vh}.paper h2{font-size:1.2rem}.prose{font-size:.98rem}.chart{min-height:185px}.numbers th,.numbers td{padding:7px}.nav button{padding:9px 11px}.jump{flex-basis:100%;order:3}.dots{display:none}.table-wrap{font-size:.85rem}}''',
        js=r'''
        export default function({data,parentElement}) {
          const root=parentElement.querySelector('#pt-pages');root.replaceChildren();
          const pages=data.pages,storageKey='insight-pt-page-v1:'+data.id+':'+data.mode;
          const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
          let index=0;try{index=Number(localStorage.getItem(storageKey))||0;}catch{}index=Math.min(pages.length-1,Math.max(0,index));
          const colors=['#526e33','#9aaf77','#557b97','#b57b43','#83739e','#aa6669','#688f83'];
          const num=v=>Number.isInteger(v)?v.toLocaleString('ko-KR'):String(v);
          const svgEl=(name,attrs,text)=>{const e=document.createElementNS('http://www.w3.org/2000/svg',name);Object.entries(attrs||{}).forEach(([k,v])=>e.setAttribute(k,String(v)));if(text!==undefined)e.textContent=text;return e;};
          const drawChart=(chart,host)=>{
            host.append(el('div',chart.title,'chart-title'),el('p','단위: '+chart.unit+' · '+chart.period,'chart-meta'));
            if(chart.kind==='bar'){
              const range=chart.rows.flatMap(r=>r.slice(1)),lo=Math.min(0,...range),hi=Math.max(0,...range),spread=hi-lo||1;
              const x=v=>(v-lo)/spread*100,base=x(0),figure=el('figure');figure.style.margin='12px 0';figure.setAttribute('aria-label',chart.title);
              chart.rows.forEach(r=>{const group=el('div',undefined,'bar-group');group.append(el('div',r[0],'category'));r.slice(1).forEach((v,i)=>{const line=el('div',undefined,'bar-line'),track=el('div',undefined,'track'),bar=el('div',undefined,'bar'),zero=el('span',undefined,'zero');zero.style.left=base+'%';bar.style.left=Math.min(x(v),base)+'%';bar.style.width=Math.max(Math.abs(x(v)-base),.15)+'%';bar.style.background=colors[i];track.append(zero,bar);line.append(el('span',chart.columns[i+1],'bar-name'),track,el('span',num(v),'bar-value'));group.append(line);});figure.append(group);});
              figure.append(el('p','공통 축 범위: '+num(lo)+' ~ '+num(hi),'chart-meta'));host.append(figure);
            }
            const wrap=el('div',undefined,'table-wrap'),table=el('table',undefined,'numbers'),head=el('thead'),tr=el('tr');chart.columns.forEach(c=>{const th=el('th',c);th.scope='col';tr.append(th);});head.append(tr);table.append(head);
            const body=el('tbody');chart.rows.forEach(r=>{const tr=el('tr');r.forEach(c=>tr.append(el('td',typeof c==='number'?num(c):String(c),typeof c==='number'?'n':'')));body.append(tr);});table.append(body);wrap.append(table);host.append(wrap,el('p',chart.note,'note'));
          };
          const go=next=>{index=Math.max(0,Math.min(pages.length-1,next));try{localStorage.setItem(storageKey,index);}catch{}draw();};
          const makeNav=(bottom=false)=>{const nav=el('div',undefined,bottom?'foot':'nav'),prev=el('button','← 이전'),next=el('button','다음 →');prev.type=next.type='button';prev.disabled=index===0;next.disabled=index===pages.length-1;prev.setAttribute('aria-label',bottom?'하단 이전 페이지':'이전 페이지');next.setAttribute('aria-label',bottom?'하단 다음 페이지':'다음 페이지');prev.onclick=()=>go(index-1);next.onclick=()=>go(index+1);nav.append(prev,el('span',`${index+1} / ${pages.length}`,'count'));
            if(!bottom){const select=el('select',undefined,'jump');select.setAttribute('aria-label','페이지 바로 이동');pages.forEach((p,i)=>{const opt=el('option',`${i+1}. ${p.label} · ${p.heading}`);opt.value=i;select.append(opt);});select.value=index;select.onchange=()=>go(Number(select.value));nav.append(select);}nav.append(next);return nav;};
          const draw=()=>{root.replaceChildren();root.append(makeNav());const page=pages[index],paper=el('article',undefined,'paper');paper.setAttribute('aria-label',`${index+1}페이지 ${page.heading}`);paper.append(el('p',page.meta||'','meta'),el('h2',page.heading));if(page.body)paper.append(el('p',page.body,'prose'));(page.blocks||[]).forEach(b=>{const block=el('section',undefined,'block');block.append(el('h3',b.heading),el('p',b.body,'prose'));paper.append(block);});if(page.chart)drawChart(page.chart,paper);if(page.source)paper.append(el('p',page.source,'source'));root.append(paper,makeNav(true));const dots=el('div',undefined,'dots');pages.forEach((p,i)=>{const b=el('button',p.label,i===index?'active':'');b.type='button';b.setAttribute('aria-label',`${i+1}페이지 ${p.label}`);if(i===index)b.setAttribute('aria-current','page');b.onclick=()=>go(i);dots.append(b);});root.append(dots);};
          root.onkeydown=e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(index+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(index-1);}};draw();
        }''')(data={'id':value['id'],'mode':key,'pages':pages}, key=key+'_'+value['id'])
